/* @autogenerated */
import { Directive, TemplateRef, viewChild } from '@angular/core';
import { BaseAction } from './base-action';

/**
 * Acción de detalle: muestra el elemento seleccionado.
 *
 * La plantilla de la subclase declara `#formTemplate` con la vista de detalle sobre `selection()[0]`.
 * Visible con el permiso `retrieve` del ACL genérico.
 */
@Directive()
export abstract class BaseDetailAction<T> extends BaseAction<T> {
  readonly name = 'detail';
  override readonly render = viewChild<TemplateRef<any>>('formTemplate');

  protected override get permission(): string {
    return 'retrieve';
  }

  run(): void {}
}
